import assert from "node:assert/strict";
const { onInbound, check } = await import("<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/courier-g5-3/bot.mjs");
const H = 3600e3, D = 24 * H;
const t0 = new Date("2026-10-23T10:00:00Z");
const at = (ms) => new Date(t0.getTime() + ms);
let n = 0;
const t = (name, fn) => { fn(); n++; };

t("never wrote -> blocked both types", () => {
  assert.deepEqual(check("new", "template", at(0)), { allowed: false, rule: "no-prior-inbound" });
  assert.deepEqual(check("new", "freeform", at(0)), { allowed: false, rule: "no-prior-inbound" });
});
t("freeform inside window allowed", () => {
  onInbound("a", "hi", at(0));
  assert.deepEqual(check("a", "freeform", at(D - 1)), { allowed: true, rule: null });
});
t("freeform at exactly 24h blocked, template allowed", () => {
  assert.deepEqual(check("a", "freeform", at(D)), { allowed: false, rule: "freeform-window-closed" });
  assert.deepEqual(check("a", "template", at(D + 5 * H)), { allowed: true, rule: null });
});
t("new inbound reopens window", () => {
  onInbound("a", "still there", at(2 * D));
  assert.equal(check("a", "freeform", at(2 * D + H)).allowed, true);
});
t("unknown type and invalid now fail closed", () => {
  assert.equal(check("a", "email", at(2 * D)).rule, "unknown-type");
  assert.equal(check("a", "freeform", new Date("x")).rule, "invalid-now");
});
t("stop variants opt out, all types blocked", () => {
  for (const s of ["STOP", "stop", " Stop. ", "STOP!!", "stop 🛑", "​STOP", "ＳＴＯＰ", "stop all", "STOPALL", "unsubscribe", "Cancel", "END", "quit"]) {
    onInbound("b", "hi", at(0));
    onInbound("b", s, at(1000));
    assert.deepEqual(check("b", "template", at(2000)), { allowed: false, rule: "opted-out" }, s);
    assert.equal(check("b", "freeform", at(2000)).rule, "opted-out", s);
  }
});
t("ordinary sentences with keywords do not opt out", () => {
  for (const s of ["please don't stop", "stop by tomorrow", "the bus will end soon", "I want to quit my plan?", "start my new plan", "Can you cancel nothing"]) {
    onInbound("c", "hi", at(0));
    onInbound("c", s, at(1000));
    assert.equal(check("c", "template", at(2000)).allowed, true, s);
  }
});
t("START restarts after STOP", () => {
  onInbound("b", "start", at(5000));
  assert.deepEqual(check("b", "template", at(6000)), { allowed: true, rule: null });
  onInbound("b", "UNSTOP", at(7000));
  assert.equal(check("b", "template", at(8000)).allowed, true);
});
t("out-of-order: older START does not undo newer STOP", () => {
  onInbound("d", "hi", at(0));
  onInbound("d", "STOP", at(9000));
  onInbound("d", "START", at(4000));
  assert.equal(check("d", "template", at(10000)).rule, "opted-out");
});
t("out-of-order: STOP delivered late still wins over earlier START", () => {
  onInbound("e", "hi", at(0));
  onInbound("e", "START", at(4000));
  onInbound("e", "STOP", at(3000));
  assert.equal(check("e", "template", at(10000)).rule, "opted-out");
});
t("out-of-order inbound does not shrink window", () => {
  onInbound("f", "hi", at(D));
  onInbound("f", "old", at(0));
  assert.equal(check("f", "freeform", at(D + H)).allowed, true);
});
t("users are isolated", () => {
  assert.equal(check("b", "template", at(2000)).rule, "opted-out");
  assert.equal(check("a", "template", at(2000)).allowed, true);
});
t("onInbound rejects invalid at", () => {
  assert.throws(() => onInbound("g", "hi", "2026-10-23"), TypeError);
});
console.log(`ok: ${n} test groups`);
EOF
